    11	use constant MAX_CONFIG_BYTES => 65_536;
    12	use constant MAX_CONFIG_LINE_BYTES => 4_096;
    13	
    14	sub _trim {
    15	    my ($value) = @_;
    16	    $value =~ s/\A\s+//;
    17	    $value =~ s/\s+\z//;
    18	    return $value;
    19	}
    20	
    21	sub _parse_value {
    22	    my ($label, $value) = @_;
    23	    $value = _trim($value);
    24	    if ($value =~ /\A"(.*)"\z/s) {
    25	        $value = $1;
    26	        $value =~ s/\\(["\\])/$1/g;
    27	    } elsif ($value =~ /\A'(.*)'\z/s) {
    28	        $value = $1;
    29	    } else {
    30	        $value =~ s/(?:\A|\s+)[;#].*\z//;
    31	        $value = _trim($value);
    32	    }
    33	    $value !~ /[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/ or fatal("$label contains control characters");
    34	    return $value;
    35	}
    36	
    37	sub parse_file {
    38	    my ($path) = @_;
    39	    open my $fh, '<', $path or fatal("missing zram-writeback config $path: $!");
    40	
    41	    my %config;
    42	    my $section = '';
    43	    my $bytes = 0;
    44	    my $line_no = 0;
    45	    while (my $line = <$fh>) {
    46	        $line_no++;
    47	        $bytes += length($line);
    48	        $bytes <= MAX_CONFIG_BYTES or fatal("zram-writeback config $path exceeds " . MAX_CONFIG_BYTES . " bytes");
    49	        length($line) <= MAX_CONFIG_LINE_BYTES or fatal("line $line_no in $path exceeds " . MAX_CONFIG_LINE_BYTES . " bytes");
    50	        chomp $line;
    51	        $line =~ s/\r\z//;
    52	        next if $line =~ /\A\s*(?:[;#]|\z)/;
    53	        if ($line =~ /\A\s*\[([A-Za-z][A-Za-z0-9_-]*)\]\s*(?:[;#].*)?\z/) {
    54	            $section = lc($1);
    55	            $config{$section} ||= {};
    56	            next;
    57	        }
    58	        $section ne '' or fatal("key outside any section at $path line $line_no");
    59	        my ($key, $value) = $line =~ /\A\s*([A-Za-z][A-Za-z0-9_-]*)\s*=\s*(.*)\z/;
    60	        defined $key or fatal("invalid INI syntax at $path line $line_no");
    61	        $key = lc($key);
    62	        exists $config{$section}{$key} and fatal("duplicate key [$section].$key at $path line $line_no");
    63	        $config{$section}{$key} = _parse_value("[$section].$key", $value);
    64	    }
    65	    close $fh or fatal("failed to read zram-writeback config $path: $!");
    66	    return \%config;
    67	}
