    37	sub _positive_min {
    38	    my (@values) = @_;
    39	    my $minimum;
    40	    for my $value (@values) {
    41	        next if !defined $value || $value <= 0;
    42	        $minimum = $value if !defined $minimum || $value < $minimum;
    43	    }
    44	    return $minimum;
    45	}
