    47	sub _device_sysfs_name {
    48	    my ($device) = @_;
    49	    return undef if !defined $device || $device eq '';
    50	    my $canonical = canonical_path($device);
    51	    return undef if !defined $canonical || $canonical eq '';
    52	    my $name = basename($canonical);
    53	    return $name =~ /\A[A-Za-z0-9_.:+-]+\z/ ? $name : undef;
    54	}
