    83	sub _writeback_batch_size_for_state {
    84	    my ($state, $queue_depth, $rotational) = @_;
    85	    _validate_state($state);
    86	
    87	    my $configured_max = cfg('ZRAM_WRITEBACK_BATCH_SIZE');
    88	    my $target = cfg('ZRAM_WRITEBACK_BATCH_SIZE_ADAPTIVE')
    89	        ? cfg($STATE_BATCH_KEY{$state})
    90	        : $configured_max;
    91	
    92	    $target = _positive_min($target, $configured_max);
    93	    $target = _positive_min($target, cfg('ZRAM_WRITEBACK_BATCH_SIZE_ROTATIONAL_MAX'))
    94	        if defined $rotational && $rotational == 1;
    95	    $target = _positive_min($target, $queue_depth);
    96	    return defined $target && $target > 0 ? $target : 1;
    97	}
