   478	        ' recompress=' . scalar(@{$plan->{recompress}}) .
   479	        ' writeback=' . scalar(@{$plan->{writeback}}) .
   480	        ' budget_allows=' . $plan->{budget_allows} .
   481	        ' writeback_batch_size=' . $tuning->{effective_batch_size} .
   482	        ' writeback_pass_pages=' . $plan->{writeback_pass_pages} .
   483	        (defined $budget_pages_available ? " writeback_budget_pages=$budget_pages_available" : '')
   484	    );
