   303	            "tracked_pages=$stats{tracked_pages} hot_pages=$stats{hot_pages} " .
   304	            "warm_pages=$stats{warm_pages} cold_pages=$stats{cold_pages} idle_pages=$stats{idle_pages} " .
   305	            "targeted_idle_pages=$stats{targeted_idle_pages} huge_idle_pages=$stats{huge_idle_pages} " .
   306	            "targeted_huge_idle_pages=$stats{targeted_huge_idle_pages} incompressible_pages=$stats{incompressible_pages} " .
