   315	sub new_range_builder {
   316	    my (%opts) = @_;
   317	    defined $opts{max_spec_bytes} && $opts{max_spec_bytes} > 0
   318	        or fatal('page-index builder max_spec_bytes must be positive');
   319	    defined $opts{max_chunks} && $opts{max_chunks} > 0
   320	        or fatal('page-index builder max_chunks must be positive');
   321	    return {
   322	        start => undef,
   323	        end => undef,
   324	        chunks => [],
   325	        current_tokens => [],
   326	        current_len => 0,
   327	        current_pages => 0,
   328	        selected_pages => 0,
   329	        max_pages => $opts{max_pages} || 0,
   330	        chunk_page_limit => $opts{chunk_page_limit} || 0,
   331	        max_spec_bytes => $opts{max_spec_bytes},
   332	        max_chunks => $opts{max_chunks},
   333	        pages => 0,
   334	        emitted_pages => 0,
   335	        truncated => 0,
   336	        capped => 0,
   337	    };
   338	}
   339	
   340	sub add_page_index_range {
   341	    my ($builder, $page_index) = @_;
   342	    return if $builder->{truncated};
   343	    $builder->{pages}++;
   344	    if ($builder->{max_pages} > 0 && $builder->{selected_pages} >= $builder->{max_pages}) {
   345	        $builder->{capped} = 1;
   346	        return;
   347	    }
   348	    $builder->{selected_pages}++;
   349	    if (!defined $builder->{start}) {
   350	        $builder->{start} = $page_index;
   351	        $builder->{end} = $page_index;
   352	        return;
   353	    }
   354	    if ($page_index == $builder->{end} + 1) {
   355	        $builder->{end} = $page_index;
   356	        return;
   357	    }
   358	    _flush_page_index_range($builder);
   359	    if (!$builder->{truncated}) {
   360	        $builder->{start} = $page_index;
   361	        $builder->{end} = $page_index;
   362	    }
   363	}
   364	
   365	sub _flush_page_index_range {
   366	    my ($builder) = @_;
   367	    return if !defined $builder->{start};
   368	    my $start = $builder->{start};
   369	    my $end = $builder->{end};
   370	    my $page_limit = $builder->{chunk_page_limit};
   371	    while ($start <= $end) {
   372	        my $slice_end = $end;
   373	        if ($page_limit > 0 && ($slice_end - $start + 1) > $page_limit) {
   374	            $slice_end = $start + $page_limit - 1;
   375	        }
   376	        my $range_pages = $slice_end - $start + 1;
   377	        my $token = $start == $slice_end
   378	            ? 'page_index=' . $start
   379	            : 'page_indexes=' . $start . '-' . $slice_end;
   380	        _add_range_token($builder, $token, $range_pages);
   381	        last if $builder->{truncated};
   382	        $start = $slice_end + 1;
   383	    }
   384	    $builder->{start} = undef;
   385	    $builder->{end} = undef;
   386	}
   387	
   388	sub _add_range_token {
   389	    my ($builder, $token, $range_pages) = @_;
   390	    return if $builder->{truncated};
   391	    if (!@{$builder->{current_tokens}} && @{$builder->{chunks}} >= $builder->{max_chunks}) {
   392	        $builder->{truncated} = 1;
   393	        return;
   394	    }
   395	    length($token) <= $builder->{max_spec_bytes}
   396	        or fatal('page-index token exceeds configured writeback spec limit');
   397	    my $page_limit = $builder->{chunk_page_limit};
   398	    if ($page_limit > 0 && @{$builder->{current_tokens}} && ($builder->{current_pages} + $range_pages) > $page_limit) {
   399	        _finalize_current_chunk($builder);
   400	        return if $builder->{truncated};
   401	        if (@{$builder->{chunks}} >= $builder->{max_chunks}) {
   402	            $builder->{truncated} = 1;
   403	            return;
   404	        }
   405	    }
   406	    my $new_len = $builder->{current_len} + length($token) + (@{$builder->{current_tokens}} ? 1 : 0);
   407	    if ($new_len > $builder->{max_spec_bytes}) {
   408	        _finalize_current_chunk($builder);
   409	        return if $builder->{truncated};
   410	        if (@{$builder->{chunks}} >= $builder->{max_chunks}) {
   411	            $builder->{truncated} = 1;
   412	            return;
   413	        }
   414	        $new_len = length($token);
   415	    }
   416	    push @{$builder->{current_tokens}}, $token;
   417	    $builder->{current_len} = $new_len;
   418	    $builder->{current_pages} += $range_pages;
   419	    $builder->{emitted_pages} += $range_pages;
   420	}
   421	
   422	sub _finalize_current_chunk {
   423	    my ($builder) = @_;
   424	    return if !@{$builder->{current_tokens}};
   425	    if (@{$builder->{chunks}} >= $builder->{max_chunks}) {
   426	        $builder->{truncated} = 1;
   427	        $builder->{current_tokens} = [];
   428	        $builder->{current_len} = 0;
   429	        $builder->{current_pages} = 0;
   430	        return;
   431	    }
   432	    push @{$builder->{chunks}}, join(' ', @{$builder->{current_tokens}});
   433	    $builder->{current_tokens} = [];
   434	    $builder->{current_len} = 0;
   435	    $builder->{current_pages} = 0;
   436	}
   437	
   438	sub finish_page_index_ranges {
   439	    my ($builder) = @_;
   440	    _flush_page_index_range($builder);
   441	    _finalize_current_chunk($builder);
   442	    return @{$builder->{chunks}};
   443	}
   444	
   445	sub block_state_authoritative {
   446	    my ($stats) = @_;
   447	    return ($stats->{block_state_available} && !$stats->{block_state_truncated}) ? 1 : 0;
   448	}
   449	
   450	sub candidate_count {
   451	    my ($stats, @keys) = @_;
   452	    my $count = 0;
   453	    for my $key (@keys) {
   454	        my $value = $stats->{$key} || 0;
   455	        $count = $value if $value > $count;
   456	    }
   457	    return $count;
   458	}
   459	
   460	sub has_candidate {
   461	    my ($stats, @keys) = @_;
   462	    return 1 if !block_state_authoritative($stats);
   463	    return candidate_count($stats, @keys) > 0 ? 1 : 0;
   464	}
   465	
   466	sub has_candidate_at_least {
   467	    my ($stats, $minimum, @keys) = @_;
   468	    return 1 if !block_state_authoritative($stats);
   469	    return candidate_count($stats, @keys) >= $minimum ? 1 : 0;
   470	}
   471	
   472	sub has_huge_idle_candidate {
   473	    my ($stats) = @_;
   474	    return 1 if !block_state_authoritative($stats);
   475	    return ($stats->{huge_idle_pages} || 0) > 0 ? 1 : 0;
