    51	sub _write_state {
    52	    my ($state) = @_;
    53	    ensure_runtime_dir();
    54	    my $path = budget_state_file();
    55	    my $tmp = "$path.tmp.$$";
    56	    open my $fh, '>', $tmp or fatal("failed to write $tmp: $!");
    57	    for my $key (sort keys %{$state}) {
    58	        my $value = defined $state->{$key} ? $state->{$key} : '';
    59	        $value =~ s/[\r\n]//g;
    60	        print {$fh} "$key=$value\n" or fatal("failed to write $tmp: $!");
    61	    }
    62	    close $fh or fatal("failed to close $tmp: $!");
    63	    chmod 0600, $tmp;
    64	    rename $tmp, $path or fatal("failed to install $path: $!");
    65	}
