    67	sub refresh_daily_writeback_budget {
    68	    return 0 if !cfg('ZRAM_WRITEBACK_ENABLED');
    69	    return 0 if !cfg('ZRAM_WRITEBACK_LIMIT_ENABLE');
    70	    my $daily_bytes = cfg('ZRAM_DAILY_WRITEBACK_LIMIT_BYTES');
    71	    return 0 if $daily_bytes <= 0;
    72	
    73	    my $today = _today_utc();
    74	    my $state = _read_state();
    75	    return 0 if ($state->{daily_budget_date} || '') eq $today;
    76	
    77	    my $pages = bytes_to_writeback_pages('writeback.daily_writeback_limit', $daily_bytes);
    78	    if ($pages <= 0) {
    79	        log_msg('warning', 'configured zram daily writeback limit is below one 4 KiB page; budget reset skipped');
    80	        return 0;
    81	    }
    82	
    83	    my $sysfs = cfg('ZRAM_SYSFS');
    84	    my $limit_written = write_attr_optional("$sysfs/writeback_limit", $pages, 'zram daily writeback_limit');
    85	    my $enable_written = write_attr_optional("$sysfs/writeback_limit_enable", 1, 'zram writeback_limit_enable');
    86	    return 0 if !$limit_written || !$enable_written;
    87	
    88	    $state->{daily_budget_date} = $today;
    89	    $state->{daily_budget_pages} = $pages;
    90	    _write_state($state);
    91	    log_msg('info', "zram daily writeback budget reset to $pages pages");
    92	    return 1;
    93	}
