   100	sub writeback_budget_pages_available {
   101	    return 0 if !cfg('ZRAM_WRITEBACK_ENABLED');
   102	    return undef if !cfg('ZRAM_WRITEBACK_LIMIT_ENABLE');
   103	    my $remaining = writeback_budget_remaining();
   104	    return 0 if !defined $remaining;
   105	    my $reserve = cfg('ZRAM_WRITEBACK_MIN_REMAINING_PAGES');
   106	    return 0 if $remaining <= $reserve;
   107	    return $remaining - $reserve;
   108	}
