    13	sub _mem_available_percent {
    14	    my $snapshot = memory_pressure_snapshot();
    15	    my $available = $snapshot->{mem_available_bytes};
    16	    my $total = $snapshot->{mem_total_bytes};
    17	    my $available_pct = $total > 0 ? int(($available * 100 + $total - 1) / $total) : 0;
    18	    return (
    19	        $available,
    20	        $total,
    21	        $available_pct,
    22	        $snapshot->{psi_some_avg10_millionths},
    23	        $snapshot->{psi_full_avg10_millionths},
    24	    );
    25	}
    26	
    27	sub determine_pressure_state {
    28	    return ('normal', ['pressure policy disabled'], {}) if !cfg('ZRAM_PRESSURE_ENABLED');
    29	
    30	    my ($available, $total, $available_pct, $some_avg10, $full_avg10) = _mem_available_percent();
    31	    my $minimum_free = cfg('ZRAM_MIN_FREE_MEMORY_BYTES');
    32	    my @reasons;
    33	
    34	    log_msg(
    35	        'debug',
    36	        'memory pressure gates ' .
    37	        "some_avg10_millionths=$some_avg10 full_avg10_millionths=$full_avg10 " .
    38	        "mem_available_bytes=$available mem_total_bytes=$total mem_available_pct=$available_pct " .
    39	        "min_free_memory_bytes=$minimum_free"
    40	    );
    41	
    42	    if (($total > 0 && $available_pct <= cfg('ZRAM_EMERGENCY_MEM_AVAILABLE_PCT'))
    43	        || $some_avg10 >= cfg('ZRAM_EMERGENCY_SOME_AVG10_THRESHOLD_UNITS')
    44	        || $full_avg10 >= cfg('ZRAM_EMERGENCY_FULL_AVG10_THRESHOLD_UNITS')) {
    45	        push @reasons, "MemAvailablePct=$available_pct<=" . cfg('ZRAM_EMERGENCY_MEM_AVAILABLE_PCT')
    46	            if $total > 0 && $available_pct <= cfg('ZRAM_EMERGENCY_MEM_AVAILABLE_PCT');
    47	        push @reasons, 'PSI some avg10 reached emergency threshold'
    48	            if $some_avg10 >= cfg('ZRAM_EMERGENCY_SOME_AVG10_THRESHOLD_UNITS');
    49	        push @reasons, 'PSI full avg10 reached emergency threshold'
    50	            if $full_avg10 >= cfg('ZRAM_EMERGENCY_FULL_AVG10_THRESHOLD_UNITS');
    51	        return ('emergency', \@reasons, {
    52	            mem_available_bytes => $available,
    53	            mem_total_bytes => $total,
    54	            mem_available_percent => $available_pct,
    55	            psi_some_avg10_millionths => $some_avg10,
    56	            psi_full_avg10_millionths => $full_avg10,
    57	        });
    58	    }
    59	
    60	    if (($total > 0 && $available_pct <= cfg('ZRAM_PRESSURE_MEM_AVAILABLE_PCT'))
    61	        || $some_avg10 >= cfg('ZRAM_PRESSURE_SOME_AVG10_THRESHOLD_UNITS')
    62	        || $full_avg10 >= cfg('ZRAM_PRESSURE_FULL_AVG10_THRESHOLD_UNITS')
    63	        || ($minimum_free > 0 && $available > 0 && $available <= $minimum_free)) {
    64	        push @reasons, "MemAvailablePct=$available_pct<=" . cfg('ZRAM_PRESSURE_MEM_AVAILABLE_PCT')
    65	            if $total > 0 && $available_pct <= cfg('ZRAM_PRESSURE_MEM_AVAILABLE_PCT');
    66	        push @reasons, 'PSI some avg10 reached pressure threshold'
    67	            if $some_avg10 >= cfg('ZRAM_PRESSURE_SOME_AVG10_THRESHOLD_UNITS');
    68	        push @reasons, 'PSI full avg10 reached pressure threshold'
    69	            if $full_avg10 >= cfg('ZRAM_PRESSURE_FULL_AVG10_THRESHOLD_UNITS');
    70	        push @reasons, 'MemAvailable bytes below configured floor'
    71	            if $minimum_free > 0 && $available > 0 && $available <= $minimum_free;
    72	        return ('pressure', \@reasons, {
    73	            mem_available_bytes => $available,
    74	            mem_total_bytes => $total,
    75	            mem_available_percent => $available_pct,
    76	            psi_some_avg10_millionths => $some_avg10,
    77	            psi_full_avg10_millionths => $full_avg10,
    78	        });
    79	    }
    80	
    81	    return ('normal', ['below pressure thresholds'], {
    82	        mem_available_bytes => $available,
    83	        mem_total_bytes => $total,
    84	        mem_available_percent => $available_pct,
    85	        psi_some_avg10_millionths => $some_avg10,
    86	        psi_full_avg10_millionths => $full_avg10,
    87	    });
    88	}
    89	
    90	sub memory_pressure_gate_met {
    91	    my ($state) = determine_pressure_state();
    92	    return $state eq 'normal' ? 0 : 1;
    93	}
