    11	our @EXPORT_OK = qw(
    12	  read_first_line read_uint_attr normalize_attr write_attr_optional write_attr_required
    13	  try_values zram_fill_pct recompress_spec writeback_spec compact_device
    14	);
    15	
    16	use constant MAX_ATTR_BYTES => 65_536;
    17	
    18	sub read_first_line {
    19	    my ($path) = @_;
    20	    open my $fh, '<', $path or return undef;
    21	    my $line = <$fh>;
    22	    close $fh;
    23	    return undef if !defined $line;
    24	    chomp $line;
    25	    return $line;
    26	}
    27	
    28	sub read_uint_attr {
    29	    my ($path) = @_;
    30	    my $line = read_first_line($path);
    31	    return undef if !defined $line || $line !~ /\A([0-9]+)/;
    32	    return 0 + $1;
    33	}
    34	
    35	sub normalize_attr {
    36	    my ($path) = @_;
    37	    open my $fh, '<', $path or return undef;
    38	    my $buffer = '';
    39	    while (1) {
    40	        my $remaining = MAX_ATTR_BYTES - length($buffer);
    41	        last if $remaining <= 0;
    42	        my $read = read($fh, my $chunk, $remaining);
    43	        last if !defined $read || $read == 0;
    44	        $buffer .= $chunk;
    45	    }
    46	    close $fh;
    47	    $buffer =~ s/\s+/ /g;
    48	    $buffer =~ s/\A //;
    49	    $buffer =~ s/ \z//;
    50	    return $buffer eq '' ? undef : $buffer;
    51	}
    52	
    53	sub _dry_run {
    54	    return cfg_default('ZRAM_DRY_RUN', 0) ? 1 : 0;
    55	}
    56	
    57	sub write_attr_optional {
    58	    my ($path, $value, $desc) = @_;
    59	    return 0 if !-e $path || !-w $path;
    60	    if (_dry_run()) {
    61	        log_msg('info', "dry-run: would set $desc via $path to '$value'");
    62	        return 1;
    63	    }
    64	    my $fh;
    65	    if (!open $fh, '>', $path) {
    66	        log_msg('warning', "failed to set optional $desc via $path: $!");
    67	        return 0;
    68	    }
    69	    my $ok = print {$fh} "$value\n";
    70	    $ok = close($fh) && $ok;
    71	    if (!$ok) {
    72	        my $error = $! || 'write rejected';
    73	        log_msg('warning', "failed to set optional $desc via $path: $error");
    74	        return 0;
    75	    }
    76	    return 1;
    77	}
    78	
    79	sub write_attr_required {
    80	    my ($path, $value, $desc) = @_;
    81	    -e $path && -w $path or fatal("$desc is unavailable at $path");
    82	    return 1 if write_attr_optional($path, $value, $desc);
    83	    fatal("failed to set $desc via $path");
    84	}
    85	
    86	sub try_values {
    87	    my ($path, $desc, @values) = @_;
    88	    return 0 if !-e $path || !-w $path;
    89	    my $attempted = 0;
    90	    my $last_error = '';
    91	    for my $value (@values) {
    92	        next if !defined $value || $value eq '';
    93	        $attempted = 1;
    94	        if (_dry_run()) {
    95	            log_msg('info', "dry-run: would set $desc via $path to '$value'");
    96	            return 1;
    97	        }
    98	        my $fh;
    99	        if (open $fh, '>', $path) {
   100	            my $ok = print {$fh} "$value\n";
   101	            $ok = close($fh) && $ok;
   102	            return 1 if $ok;
   103	            $last_error = "$!";
   104	        } else {
   105	            $last_error = "$!";
   106	        }
   107	        $last_error = 'write rejected' if $last_error eq '';
   108	    }
   109	    if (!$attempted) {
   110	        log_msg('warning', "no non-empty candidate values supplied for $desc via $path");
   111	    } elsif ($last_error ne '') {
   112	        log_msg('warning', "none of the candidate values worked for $desc via $path: $last_error");
   113	    } else {
   114	        log_msg('warning', "none of the candidate values worked for $desc via $path");
   115	    }
   116	    return 0;
   117	}
   118	
   119	sub zram_fill_pct {
   120	    my $sysfs = cfg('ZRAM_SYSFS');
   121	    my $disksize = read_uint_attr("$sysfs/disksize");
   122	    return 0 if !defined $disksize || $disksize <= 0;
   123	    my $mm_stat = read_first_line("$sysfs/mm_stat");
